    # Create a dictionary to map encoded letters to original letters
    encoding_dict = {}
    for i, letter in enumerate(encoded):
        if letter not in encoding_dict:
            encoding_dict[letter] = original[i]

    # Check for contradictions in the encoding
    for letter in encoding_dict:
        if encoding_dict[letter] != original[encoded.index(letter)]:
            return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for letter in message:
        if letter in encoding_dict:
            decoded += encoding_dict[letter]
        else:
            return "Failed"

