def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill the table with the base case
    for i in range(n + 1):
        dp[0][i] = 0

    # Fill the table with the values for the rest of the subproblems
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] > i:
                dp[i][j] = dp[i][j - 1]
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])

    # Return the minimum remaining space in the box after packing all items
    return V - dp[V][n]
